<?php
declare(strict_types=1); require_once __DIR__.'/../../config/config.php'; app_boot(); $userId=require_auth(); $action=$_GET['action']??$_POST['action']??''; $pdo=db();
if($action==='list'){ $st=$pdo->prepare('SELECT media_id FROM favorites WHERE user_id=?');$st->execute([$userId]);json_response(true,'Favorites',array_map(fn($r)=>(string)$r['media_id'],$st->fetchAll())); }
if($action==='toggle'){ require_method('POST');$d=request_json();$mid=(int)($d['mediaId']??0);if(!$mid)json_response(false,'Invalid media id.',null,422);$q=$pdo->prepare('SELECT 1 FROM favorites WHERE user_id=? AND media_id=?');$q->execute([$userId,$mid]);if($q->fetch()){ $pdo->prepare('DELETE FROM favorites WHERE user_id=? AND media_id=?')->execute([$userId,$mid]);$pdo->prepare("INSERT INTO analytics_events(event_type,user_id,media_id) VALUES('favorite_remove',?,?)")->execute([$userId,$mid]);json_response(true,'Removed from Favorites',['active'=>false]); } $pdo->prepare('INSERT INTO favorites(user_id,media_id) VALUES(?,?)')->execute([$userId,$mid]);$pdo->prepare("INSERT INTO analytics_events(event_type,user_id,media_id) VALUES('favorite_add',?,?)")->execute([$userId,$mid]);json_response(true,'Added to Favorites',['active'=>true]); }
json_response(false,'Unknown favorites action.',null,400);
